function uniquePathsWithObstacles(grid) {
  const m = grid.length, n = grid[0].length;
  const memo = new Map();
  const paths = (r, c) => {
    if (r < 0 || c < 0 || grid[r][c] === 1) return 0;    // off the grid or blocked
    if (r === 0 && c === 0) return 1;
    const key = r * n + c;
    if (!memo.has(key)) memo.set(key, paths(r - 1, c) + paths(r, c - 1));
